random(){
const{ref:box}=getElement();
const n=+box.dataset.wcardsRand||6;
const cards=[...box.children];
for(let i=cards.length-1;i>0;i--){
const j=Math.floor(Math.random()*(i+1));
[cards[i],cards[j]]=[cards[j],cards[i]];
}
cards.forEach((c,k)=>{
if(k<n){
c.hidden=false;
box.appendChild(c);
}else{
c.remove();
}
});
},
